CREATE OR REPLACE VIEW public.vw_lab_producao_classificada WITH (security_invoker=true) AS SELECT p.id,p.feegow_id,p.paciente_id,p.paciente_nome,p.agendamento_id,p.data_execucao,p.hora_inicio,p.profissional_id,p.profissional_nome,p.procedimento_id,p.procedimento_nome,p.valor,p.convenio_nome,p.unidade_id,p.created_at,p.prontuario,p.id_transacao,p.n_guia_prestador,p.convenio_id,p.valor_pago,p.situacao,p.situacao_conta,p.grupo_id,
public.lab_grupo_exibicao(CASE WHEN p.grupo_fonte='manual' OR nullif(btrim(p.grupo_nome),'') IS NULL OR p.grupo_nome IN ('Não informado','Não classificado','Sem grupo') THEN coalesce((SELECT m.grupo_nome FROM public.dim_grupo_procedimento_manual m WHERE m.procedimento_chave=public.dre_feegow_normalizar_nome(p.procedimento_nome)),p.grupo_nome) ELSE p.grupo_nome END) grupo_nome,
p.tipo_procedimento,p.forma_pagamento,p.tipo_guia,p.grupo_nome grupo_nome_original,p.grupo_fonte FROM public.lab_producao_feegow p;
CREATE OR REPLACE VIEW public.vw_producao_sem_grupo WITH (security_invoker=true) AS WITH candidatos AS MATERIALIZED (SELECT procedimento_nome,procedimento_id,valor FROM public.lab_producao_feegow WHERE nullif(btrim(grupo_nome),'') IS NULL OR grupo_nome IN ('Não informado','Não classificado','Sem grupo')) SELECT p.procedimento_nome,p.procedimento_id,count(*) qtd,coalesce(sum(p.valor),0) valor FROM candidatos p WHERE NOT EXISTS (SELECT 1 FROM public.dim_grupo_procedimento_manual m WHERE m.procedimento_chave=public.dre_feegow_normalizar_nome(p.procedimento_nome)) GROUP BY 1,2;
CREATE OR REPLACE VIEW public.vw_producao_sem_grupo_mensal WITH (security_invoker=true) AS WITH candidatos AS MATERIALIZED (SELECT procedimento_nome,data_execucao,valor FROM public.lab_producao_feegow WHERE nullif(btrim(grupo_nome),'') IS NULL OR grupo_nome IN ('Não informado','Não classificado','Sem grupo')) SELECT date_trunc('month',p.data_execucao)::date mes,count(*) qtd,coalesce(sum(p.valor),0) valor FROM candidatos p WHERE NOT EXISTS (SELECT 1 FROM public.dim_grupo_procedimento_manual m WHERE m.procedimento_chave=public.dre_feegow_normalizar_nome(p.procedimento_nome)) GROUP BY 1;